// Formatter v3: tickets, proyectos, fs, alertas_zabbix, contactos, empresas, dominios
const raw = $json.output || '';
let data;
try {
  const match = raw.match(/\{[\s\S]*\}/);
  if (!match) return [{ json: { output: raw } }];
  data = JSON.parse(match[0]);
} catch(e) {
  return [{ json: { output: raw } }];
}

if (!data.tipo || data.tipo === 'texto') {
  return [{ json: { output: data.mensaje || data.resumen || raw } }];
}

// Getter flexible: prueba multiples nombres, retorna el primero con valor real
function g(obj, ...names) {
  for (const n of names) {
    const v = obj[n];
    if (v !== undefined && v !== null && String(v).trim() !== '' && String(v).trim() !== '-') return v;
  }
  return '';
}

const SEP = '\n\u2796\u2796\u2796\u2796\u2796\n';
const fecha = data.fecha || new Date().toLocaleDateString('es-AR', {day:'2-digit',month:'2-digit',year:'numeric',hour:'2-digit',minute:'2-digit'});
const rows = data.datos || [];
let out = '';

// ─── TICKETS ──────────────────────────────────────────────────────────────
if (data.tipo === 'tickets') {
  const ticketMap = new Map();
  for (const r of rows) {
    const rawId = g(r, 'ticket_no', 'ticketno', 'ticket_number');
    const tid = rawId || ('TT-' + (r.ticketid || r.id || '?'));
    if (!ticketMap.has(tid)) {
      ticketMap.set(tid, {
        ticket_no: tid,
        title: g(r, 'title', 'ticket_title', 'subject', 'titulo'),
        empresa: g(r, 'empresa', 'accountname', 'account_name', 'cliente'),
        tecnico: g(r, 'tecnico', 'responsable', 'tecnico_asignado', 'assigned_user'),
        status: g(r, 'status', 'ticketstatus', 'estado'),
        descripcion: g(r, 'descripcion', 'description', 'comments'),
        fs: []
      });
    }
    const fsNo = g(r, 'contract_no', 'fs_no', 'fs_contract_no');
    const fsId = g(r, 'fieldserviceid', 'fs_id', 'fsid');
    const fsKey = fsNo || fsId;
    if (fsKey) {
      const ticket = ticketMap.get(tid);
      const already = ticket.fs.some(f => (f.contract_no || f.fsid) === fsKey);
      if (!already) {
        ticket.fs.push({
          contract_no: fsNo || fsId,
          subject: g(r, 'fs_subject', 'fs_title', 'fs_descripcion', 'fs_name'),
          horas: g(r, 'horas', 'fs_horas', 'tiempo_horas', 'resolution_hours', 'cf_930'),
          tecnico: g(r, 'fs_tecnico', 'tecnico_fs')
        });
      }
    }
  }
  out = '\ud83d\udcc5 *Tickets \u2014 ' + fecha + '*\n\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501';
  if (!ticketMap.size) { out += '\nSin tickets en el per\u00edodo.'; }
  for (const t of ticketMap.values()) {
    out += '\n\n\ud83c\udfab *' + t.ticket_no + '* \u2014 ' + (t.title || 'Sin t\u00edtulo');
    out += '\n\ud83c\udfe2 ' + (t.empresa || 'N/D') + ' | \ud83d\udc68\u200d\ud83d\udcbb ' + (t.tecnico || 'S/D');
    out += '\n\ud83d\udccc ' + (t.status || '') + (t.descripcion ? ' | \ud83d\udcdd ' + String(t.descripcion).substring(0,80) : '');
    if (t.fs.length > 0) {
      out += '\n  \u21b3 FS:';
      for (const f of t.fs) {
        out += '\n    \u25aa\ufe0f ' + (f.contract_no || '') + ': ' + (f.subject || '') + ' | \u23f1\ufe0f ' + (f.horas || 0) + 'h | \ud83d\udc64 ' + (f.tecnico || 'N/D');
      }
    } else {
      out += '\n  \u21b3 Sin FS vinculados';
    }
    out += SEP;
  }

// ─── PROYECTOS ────────────────────────────────────────────────────────────
} else if (data.tipo === 'proyectos') {
  const projMap = new Map();
  for (const r of rows) {
    const rawPid = g(r, 'project_no', 'projectno', 'project_number');
    const pid = rawPid || String(r.projectid || r.id || '?');
    if (!projMap.has(pid)) {
      projMap.set(pid, {
        project_no: pid,
        projectname: g(r, 'projectname', 'nombre', 'project_name', 'name'),
        empresa: g(r, 'empresa', 'accountname', 'account_name', 'cliente'),
        estado: g(r, 'projectstatus', 'estado', 'status'),
        descripcion: g(r, 'descripcion', 'description'),
        tareas: []
      });
    }
    const taskId = g(r, 'projecttaskid', 'taskid', 'task_id');
    const taskName = g(r, 'projecttaskname', 'taskname', 'task_name', 'tarea', 'nombre_tarea');
    if (taskId || taskName) {
      const proj = projMap.get(pid);
      const dedupKey = taskId || taskName;
      const already = proj.tareas.some(t => (t.projecttaskid || t.taskname) === dedupKey);
      if (!already) {
        proj.tareas.push({
          projecttaskid: taskId,
          taskname: taskName,
          status: g(r, 'projecttaskstatus', 'task_status', 'taskstatus', 'estado_tarea'),
          asignado: g(r, 'tecnico_asignado', 'tecnico', 'assigned_user', 'asignado'),
          order: g(r, 'task_order', 'projecttasknumber', 'taskorder', 'orden')
        });
      }
    }
  }
  out = '\ud83d\udcc5 *Proyectos \u2014 ' + fecha + '*\n\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501';
  if (!projMap.size) { out += '\nSin proyectos.'; }
  for (const p of projMap.values()) {
    out += '\n\n\ud83d\udcc1 *' + p.project_no + '* \u2014 ' + (p.projectname || 'Sin nombre');
    out += '\n\ud83c\udfe2 ' + (p.empresa || 'N/D') + ' | \ud83d\udccc ' + (p.estado || '');
    if (p.descripcion) out += '\n\ud83d\udcdd ' + String(p.descripcion).substring(0,80);
    if (p.tareas.length > 0) {
      out += '\n  \u21b3 Tareas (' + p.tareas.length + '):';
      for (const t of p.tareas) {
        const si = (t.status||'').toLowerCase();
        const icon = si.includes('progress') ? '\u23f3' : si.includes('complet') ? '\u2705' : '\u25aa\ufe0f';
        out += '\n    ' + icon + ' ' + (t.order ? '[' + t.order + '] ' : '') + (t.taskname || '') + ' | ' + (t.status || '') + ' | \ud83d\udc68\u200d\ud83d\udcbb ' + (t.asignado || 'N/D');
      }
    } else {
      out += '\n  \u21b3 Sin tareas registradas';
    }
    out += SEP;
  }

// ─── FS ───────────────────────────────────────────────────────────────────
} else if (data.tipo === 'fs') {
  // Agrupar por tecnico, ordenar, sumar horas reales (hora_fin - hora_inicio)
  const byTec = {};
  for (const f of rows) {
    const tec = g(f,'tecnico','responsable','assigned_user') || 'Sin asignar';
    if (!byTec[tec]) byTec[tec] = [];
    byTec[tec].push(f);
  }
  const hFmt = h => {
    const n = parseFloat(h) || 0;
    if (n === 0) return '0';
    const s = n.toFixed(2);
    return parseFloat(s) % 1 === 0 ? String(Math.round(n)) : s.replace(/0+$/, '');
  };
  out = '📋 *Formularios de Servicio — ' + fecha + '*\n━━━━━━━━━━━━━━';
  if (!rows.length) { out += '\nSin registros.'; }
  let totalFS = 0, totalHoras = 0;
  for (const tec of Object.keys(byTec).sort()) {
    const fsList = byTec[tec];
    let subH = 0;
    out += '\n\n👤 *' + tec + '*';
    for (const f of fsList) {
      const h = parseFloat(g(f,'horas_real','horas','tiempo_horas','cf_930')) || 0;
      subH += h; totalHoras += h; totalFS++;
      const empresa = g(f,'empresa','accountname') || 'N/D';
      const fsNo = g(f,'contract_no','fs_no','fieldserviceid') || '?';
      const hIni = g(f,'hora_inicio','hora_inicio_real') || '';
      const hFin = g(f,'hora_fin','hora_fin_real') || '';
      const rango = (hIni && hFin) ? ' | ' + hIni.substring(0,5) + '→' + hFin.substring(0,5) : '';
      out += '\n  • ' + fsNo + ' | ' + hFmt(h) + ' hs | ' + empresa + rango;
    }
    out += '\n  _Total: ' + hFmt(subH) + ' hs_';
  }
  if (rows.length) {
    out += '\n\n📊 *' + totalFS + ' FS | ' + hFmt(totalHoras) + ' horas en total*';
  }

// ─── ALERTAS ZABBIX ───────────────────────────────────────────────────────
} else if (data.tipo === 'alertas_zabbix') {
  out = '\ud83d\udcc5 *Infraestructura \u2014 ' + fecha + '*\n\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501';
  const p5 = rows.filter(i => i.severity == 5 || i.severity === 'DESASTRE');
  const p4 = rows.filter(i => i.severity == 4 || i.severity === 'ALTO');
  const otros = rows.filter(i => i.severity != 5 && i.severity != 4 && i.severity !== 'DESASTRE' && i.severity !== 'ALTO');
  if (p5.length) {
    out += '\n\n\ud83d\udd34 *DESASTRE:*';
    for (const a of p5) out += '\n\u2022 ' + g(a,'empresa_grupo','empresa','accountname') + ' | ' + g(a,'host_name','hostname','name') + ' \u2014 ' + g(a,'event_name','description','trigger_name') + (a.status==1?' \u26a1':'');
  }
  if (p4.length) {
    out += '\n\n\ud83d\udfe0 *ALTO:*';
    for (const a of p4) out += '\n\u2022 ' + g(a,'empresa_grupo','empresa','accountname') + ' | ' + g(a,'host_name','hostname','name') + ' \u2014 ' + g(a,'event_name','description','trigger_name') + (a.status==1?' \u26a1':' \u2714\ufe0f');
  }
  if (otros.length) {
    out += '\n\n\ud83d\udfe1 *MEDIO/INFO:*';
    for (const a of otros) out += '\n\u2022 ' + g(a,'empresa_grupo','empresa','accountname') + ' | ' + g(a,'host_name','hostname','name') + ' \u2014 ' + g(a,'event_name','description','trigger_name');
  }
  const activos = rows.filter(i => i.status == 1).length;
  const resueltos = rows.filter(i => i.status == 0).length;
  out += '\n\n\ud83d\udcca Total: ' + rows.length + ' | \u26a1 Activos: ' + activos + ' | \u2714\ufe0f Resueltos: ' + resueltos;

// ─── CONTACTOS ────────────────────────────────────────────────────────────
} else if (data.tipo === 'contactos') {
  out = '\ud83d\udcc5 *Contactos \u2014 ' + fecha + '*\n\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501';
  for (const c of rows) {
    out += '\n\n\ud83d\udc64 ' + g(c,'nombre','firstname','fullname','contactname','contact_name') + ' | \ud83c\udfe2 ' + g(c,'empresa','accountname','account_name');
    out += '\n\ud83d\udce7 ' + g(c,'email','mail') + ' | \ud83d\udcde ' + g(c,'telefono','phone','mobile');
    out += SEP;
  }

// ─── EMPRESAS ────────────────────────────────────────────────────────────
} else if (data.tipo === 'empresas') {
  out = '\ud83d\udcc5 *Empresas \u2014 ' + fecha + '*\n\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501';
  for (const e of rows) {
    out += '\n\n\ud83c\udfe2 ' + g(e,'accountname','nombre','company','account_name');
    out += '\n\ud83d\udcde ' + (g(e,'telefono','phone','mobile') || 'N/D') + ' | \ud83d\udce7 ' + (g(e,'email','mail') || 'N/D');
    const city = g(e,'ciudad','bill_city','city');
    if (city) out += '\n\ud83d\udccd ' + city;
    out += SEP;
  }

// ─── DOMINIOS ────────────────────────────────────────────────────────────
} else if (data.tipo === 'dominios') {
  out = '\ud83c\udf10 *Dominios \u2014 ' + fecha + '*\n\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501';
  if (!rows.length) { out += '\nSin dominios en el per\u00edodo.'; }
  else {
    const vencidos = rows.filter(d => parseInt(g(d,'dias_restantes','dias','days') || 0) < 0);
    const proximos = rows.filter(d => { const n = parseInt(g(d,'dias_restantes','dias','days') || 999); return n >= 0 && n <= 30; });
    const al_dia   = rows.filter(d => parseInt(g(d,'dias_restantes','dias','days') || 999) > 30);
    if (vencidos.length) {
      out += '\n\n\ud83d\udd34 *VENCIDOS (' + vencidos.length + '):*';
      for (const d of vencidos) {
        const dias = Math.abs(parseInt(g(d,'dias_restantes','dias','days') || 0));
        const cli  = g(d,'cliente','client','accountname');
        out += '\n\u2022 ' + g(d,'dominio','domain') + (cli ? ' | ' + cli : '') + ' | hace ' + dias + 'd | ' + (g(d,'registrar') || '');
      }
    }
    if (proximos.length) {
      out += '\n\n\u26a0\ufe0f *Vencen en \u226430d (' + proximos.length + '):*';
      for (const d of proximos) {
        const dias = parseInt(g(d,'dias_restantes','dias','days') || 0);
        const cli  = g(d,'cliente','client','accountname');
        out += '\n\u2022 ' + g(d,'dominio','domain') + (cli ? ' | ' + cli : '') + ' | en ' + dias + 'd (' + g(d,'fecha_vencimiento','fecha','expiry') + ')';
      }
    }
    if (al_dia.length) {
      out += '\n\n\u2705 *Al d\u00eda (' + al_dia.length + '):*';
      for (const d of al_dia) {
        const dias = parseInt(g(d,'dias_restantes','dias','days') || 0);
        const cli  = g(d,'cliente','client','accountname');
        out += '\n\u2022 ' + g(d,'dominio','domain') + (cli ? ' | ' + cli : '') + ' | vence en ' + dias + 'd';
      }
    }
  }

} else {
  return [{ json: { output: raw } }];
}

if (data.resumen) {
  out += '\n\ud83d\udcca *Resumen:* ' + data.resumen;
}

return [{ json: { output: out.trim() } }];
